internal sealed class Core : IDisposable
{
    private readonly Process process; private readonly SemaphoreSlim gate = new(1, 1);
    public Core() { process = Process.Start(new ProcessStartInfo(Path.Combine(AppContext.BaseDirectory, "radcore.exe")) { UseShellExecute = false, RedirectStandardInput = true, RedirectStandardOutput = true, RedirectStandardError = true, CreateNoWindow = true, WorkingDirectory = AppContext.BaseDirectory }) ?? throw new Exception(); process.ErrorDataReceived += (_, _) => { }; process.BeginErrorReadLine(); }
    public async Task<JsonNode> Call(object request) { await gate.WaitAsync(); try { await process.StandardInput.WriteLineAsync(JsonSerializer.Serialize(request)); await process.StandardInput.FlushAsync(); var line = await process.StandardOutput.ReadLineAsync().WaitAsync(TimeSpan.FromSeconds(35)); var r = JsonNode.Parse(line ?? "")!; if (r["ok"]?.GetValue<bool>() != true) throw new InvalidOperationException(r["error"]?.ToString() ?? "operation_failed"); return r["data"]?.DeepClone() ?? new JsonObject(); } finally { gate.Release(); } }
    public void Dispose() { try { process.StandardInput.Close(); if (!process.WaitForExit(8000)) process.Kill(true); } catch { } process.Dispose(); }
}
internal static class Storage
{
    public static readonly string FilePath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "RADVPN", "vault.bin");
    public static byte[] Encrypt(JsonObject state) => ProtectedData.Protect(Encoding.UTF8.GetBytes(state.ToJsonString()), null, DataProtectionScope.CurrentUser);
    public static JsonObject Decrypt(byte[] bytes) => (JsonObject)JsonNode.Parse(Encoding.UTF8.GetString(ProtectedData.Unprotect(bytes, null, DataProtectionScope.CurrentUser)))!;
    public static void Save(JsonObject state) { Directory.CreateDirectory(Path.GetDirectoryName(FilePath)!); var tmp = FilePath + ".tmp"; File.WriteAllBytes(tmp, Encrypt(state)); File.Move(tmp, FilePath, true); }
    public static JsonObject Load() => File.Exists(FilePath) ? Decrypt(File.ReadAllBytes(FilePath)) : new JsonObject { ["profiles"] = new JsonArray(), ["subscriptions"] = new JsonArray(), ["lang"] = "en", ["selected"] = "", ["tray"] = true };
}
