        var nav = new WrapPanel { Margin = new Thickness(0, 8, 0, 20) }; foreach (var p in new[] { "home", "profiles", "subscriptions", "settings", "logs", "about" }) { var target = p; nav.Children.Add(Btn(p, () => { page = target; Render(); return Task.CompletedTask; }, p == page)); }
