        if (data["settings"] == null) return; switch (page) { case "home": Home(); break; case "profiles": ProfilePage(); break; case "subscriptions": SubscriptionPage(); break; case "settings": SettingsPage(); break; case "logs": foreach (var e in events) body.Children.Add(Text(e, 14, muted)); break; case "about": body.Children.Add(Text("RADVPN 2.0.0", 28)); body.Children.Add(Text("Xray " + "26.10.21", 16, orange)); body.Children.Add(Text(T("development"))); body.Children.Add(Text(T("privacy"))); body.Children.Add(Text(T("backup_help"))); break; }
