    async Task Toggle() { if (core == null) throw new InvalidOperationException("core_start_failed"); if (active is "connecting" or "connected") { await core.Call(new { method = "stop" }); active = "disconnected"; } else { var p = Selected(); if (p == null) throw new InvalidOperationException("select_profile"); if (Settings["mode"]?.ToString() == "tunnel" && !new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator)) throw new InvalidOperationException("admin"); await core.Call(new { method = "start", profile = p, settings = Settings, fd = -1 }); active = "connecting"; } oldUp = oldDown = 0; oldSample = DateTime.UtcNow; Render(); }
