            var s = await core.Call(new { method = "status" }); var next = s["state"]?.ToString() ?? "error"; if (next != active) { events.Insert(0, DateTime.Now.ToString("HH:mm:ss") + " " + T(next)); if (events.Count > 100) events.RemoveAt(100); }
            active = next; if (status != null) status.Text = T(active); if (connect != null) connect.Content = T(active is "connected" or "connecting" ? "disconnect" : "connect"); var up = s["up"]?.GetValue<long>() ?? 0; var down = s["down"]?.GetValue<long>() ?? 0; var elapsed = Math.Max(.1, (DateTime.UtcNow - oldSample).TotalSeconds); if (metrics != null) metrics.Text = $"{T("up")}: {up:N0} B    {T("down")}: {down:N0} B\n{T("speed")}: ↑ {Math.Max(0, up - oldUp) / elapsed:N0} B/s  ↓ {Math.Max(0, down - oldDown) / elapsed:N0} B/s\n{T("duration")}: {s["seconds"]} s    {T("latency")}: {s["latency"]?.ToString() ?? "—"} ms\n{T("local")}: {s["listener"]}"; oldUp = up; oldDown = down; oldSample = DateTime.UtcNow; if (s["error"]?.ToString() is string err && err != "" && status != null) status.Text = T(err);
