    void SettingsPage() { var languages = new WrapPanel(); foreach (var l in new[] { "en", "fa" }) { var lang = l; var b = new Button { Content = l == "en" ? "English" : "فارسی" }; b.Click += (_, _) => { data["lang"] = lang; LoadWords(); UpdateTray(); Save(); Render(); }; languages.Children.Add(b); } body.Children.Add(languages); var port = Input("port", Settings["port"]!.ToString()); var bind = Input("bind", Settings["bind"]!.ToString()); var mtu = Input("mtu", Settings["mtu"]!.ToString()); var dns = Input("dns", string.Join(",", ((JsonArray)Settings["dns"]!).Select(d => d!.ToString()))); body.Children.Add(Text(T("rules_help"), 14, muted)); var rules = Input("rules", Settings["rules"]?.ToJsonString() ?? "[]", true); var trayOption = new CheckBox { Content = T("tray"), IsChecked = data["tray"]?.GetValue<bool>() ?? true, Foreground = Brushes.White, Margin = new Thickness(0, 8, 0, 16) }; body.Children.Add(trayOption); body.Children.Add(Btn("save", async () => { if (active is "connected" or "connecting") throw new InvalidOperationException("already_running"); if (!int.TryParse(port.Text, out var pn) || !int.TryParse(mtu.Text, out var mn)) throw new InvalidOperationException("invalid_settings"); var s = (JsonObject)Settings.DeepClone(); s["port"] = pn; s["bind"] = bind.Text.Trim(); s["mtu"] = mn; s["dns"] = new JsonArray(dns.Text.Split(',').Select(d => (JsonNode?)JsonValue.Create(d.Trim())).ToArray()); s["rules"] = JsonNode.Parse(rules.Text); await core!.Call(new { method = "settings", settings = s }); if (Selected() != null) await core!.Call(new { method = "validate", profile = Selected(), settings = s }); data["settings"] = s; data["tray"] = trayOption.IsChecked == true; Save(); }, true)); body.Children.Add(Text(T("backup_help"), 14, muted)); body.Children.Add(Btn("export", () => { var f = new SaveFileDialog { Filter = "RADVPN (*.radvpn)|*.radvpn" }; if (f.ShowDialog() == true) File.WriteAllBytes(f.FileName, Storage.Encrypt(data)); return Task.CompletedTask; })); body